import{_ as i,o as s,c as a,a3 as t,j as e,a as n}from"./chunks/framework.z_KJ15Ep.js";const l="/bilder/unterricht-kataloge/kataloge-adress-arten.png",A=JSON.parse('{"title":"Adressarten im Katalog vorbereiten","description":"","frontmatter":{"title":"Adressarten im Katalog vorbereiten","source_pageid":493,"source_revision":5425},"headers":[],"relativePath":"schild3/unterricht-kataloge/adress-arten-allgemeine-kataloge.md","filePath":"schild3/unterricht-kataloge/adress-arten-allgemeine-kataloge.md"}'),o={name:"schild3/unterricht-kataloge/adress-arten-allgemeine-kataloge.md"};function d(g,r,h,u,c,p){return s(),a("div",null,[...r[0]||(r[0]=[t('<h1 id="adressarten-im-katalog-vorbereiten" tabindex="-1">Adressarten im Katalog vorbereiten <a class="header-anchor" href="#adressarten-im-katalog-vorbereiten" aria-label="Permalink to &quot;Adressarten im Katalog vorbereiten&quot;">​</a></h1><p>Legen Sie die Kategorien für weitere Adressen fest, etwa Ausbildungsbetriebe oder andere schulische Kontakte. Anschließend stehen die Adressarten in den zugehörigen Auswahllisten bereit.</p><p>Adressarten beschreiben, welche Funktion eine gespeicherte Adresse hat, zum Beispiel <strong>Ausbildungsbetrieb</strong> unter <strong>Schüler → Weitere Adressen</strong>. Legen Sie die benötigten Adressarten hier im Katalog an. Anschließend stehen sie in den Auswahllisten der Adressfelder zur Verfügung.</p><p>Hier erfassen Sie die <strong>Adressarten</strong>, nicht die einzelnen Anschriften. Die zugehörigen Kontakte legen Sie unter <a href="/schild3/unterricht-kataloge/allgemeine-adressen-allgemeine-kataloge.html">Allgemeine Adressen</a> an und ordnen sie bei Bedarf unter <a href="/schild3/schueler/weitere-adressen-schueler.html">Weitere Adressen</a> einem Schülerdatensatz zu.</p>',4),e("div",{"data-hint-kind":"tip",class:"tip custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"tip","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("path",{d:"M9 18h6m-5 3h4m-5-6c-4-3-4-9 0-11 5-3 11 1 9 6-.5 2-2 3-3 5v1H9z"})]),n("Tipp")]),e("p",null,[n("Zum Beispiel ist eine Adressart "),e("em",null,"VIP"),n(" ist an einigen Schulen eingerichtet. In dieser Kategorie werden alle für das Schulleben wichtigen Personen geführt. Das sind z.B. Repräsentanten des Schulträgers, Sponsoren, ...")]),e("p",null,"Bewährt hat sich die Erfassung dieser Adressdaten für diverse Anschreiben u.a. zu Schulfesten, Abschlussveranstaltungen, Einweihungen, ...")],-1),t('<p><a href="/bilder/unterricht-kataloge/kataloge-adress-arten.png"><img src="'+l+'" alt="Anlegen und Bearbeiten von Adressarten." loading="lazy"></a></p><p><em>Anlegen und Bearbeiten von Adressarten.</em></p><p>Einträge könne mit dem &quot;<strong>+</strong>&quot; und &quot;<strong>-</strong>&quot; erstellt und entfernt werden, weiterhin lassen sich Einträge bearbeiten, sofern Sie nicht schon in Datensätzen eingebunden wurden.</p><p>Auch lässt sich die Sortierreihenfolge für die Anzeige im Dropdown-Menü über die schwarzen Pfeile links oder direkt über die Indizes unter <em>&quot;Sortierung&quot;</em> vorgeben.</p><p>Ob ein Eintrag zwar im Katalog vorhanden, im Dropdown-Menü aber ausgeblendet wird, lässt sich wie in anderen Katalogen auch mit <em>&quot;Sichtbar&quot;</em> steuern.</p><hr><p><a href="https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Adress-Arten_(Allgemeine_Kataloge)" target="_blank" rel="noreferrer">Originalartikel im Wiki</a> · Quellrevision 5425.</p>',7)])])}const b=i(o,[["render",d]]);export{A as __pageData,b as default};
